function gqStrip(src){
  return String(src||'').replace(/#[^\n]*/g,'');
}
function gqTokens(src){
  var s=gqStrip(src), out=[], re=/"(?:[^"\\]|\\.)*"|[\{\}\(\)\[\]:,=@\$!]|\.\.\.|[A-Za-z_][\w]*|\S/g, m;
  while((m=re.exec(s))!==null) out.push(m[0]);
  return out;
}
function gqBalance(src){
  var t=gqTokens(src), stack=[], pairs={'}':'{',')':'(',']':'['};
  for(var i=0;i<t.length;i++){
    if('{(['.indexOf(t[i])>=0 && t[i].length===1) stack.push(t[i]);
    else if(pairs[t[i]]){
      if(stack.pop()!==pairs[t[i]]) return { ok:false, msg:'第 '+(i+1)+' 个 token 处括号不匹配：'+t[i] };
    }
  }
  if(stack.length) return { ok:false, msg:'有 '+stack.length+' 个括号未闭合' };
  return { ok:true, msg:'' };
}
function gqParse(src){
  var text=gqStrip(src);
  if(!text.trim()) return { error:'请输入 GraphQL 查询' };
  var bal=gqBalance(text);
  if(!bal.ok) return { error:bal.msg };
  var head=text.match(/^\s*(query|mutation|subscription)?\s*([A-Za-z_]\w*)?\s*(\(([\s\S]*?)\))?\s*\{/);
  if(!head) return { error:'未找到操作体，查询应包含 { ... }' };
  var op=head[1]||'query', name=head[2]||null, varsRaw=head[4]||'';
  var vars=[], vre=/\$([A-Za-z_]\w*)\s*:\s*(\[?\s*[A-Za-z_][\w!]*\s*\]?!?)\s*(?:=\s*([^,)]+))?/g, vm;
  while((vm=vre.exec(varsRaw))!==null)
    vars.push({ name:vm[1], type:vm[2], required:/!$/.test(vm[2]), def: vm[3]? vm[3].trim() : null });
  var used={}, ure=/\$([A-Za-z_]\w*)/g, um;
  var bodyStart=text.indexOf('{', head.index);
  var body=text.slice(bodyStart);
  while((um=ure.exec(body))!==null) used[um[1]]=(used[um[1]]||0)+1;
  var frags=[], fre=/fragment\s+([A-Za-z_]\w*)\s+on\s+([A-Za-z_]\w*)/g, fm;
  while((fm=fre.exec(text))!==null) frags.push({ name:fm[1], on:fm[2] });
  var spreads=[], sre=/\.\.\.\s*([A-Za-z_]\w*)/g, sm;
  while((sm=sre.exec(text))!==null) if(sm[1]!=='on') spreads.push(sm[1]);
  var directives=[], dre=/@([A-Za-z_]\w*)/g, dm;
  while((dm=dre.exec(text))!==null) directives.push(dm[1]);
  return { error:null, op:op, name:name, vars:vars, used:used, frags:frags,
           spreads:spreads, directives:directives, body:body };
}
var GQ_KEYWORDS = ['query','mutation','subscription','fragment','on','true','false','null'];
function gqFields(body){
  var s=gqStrip(body||''), out=[], depth=0, maxDepth=0, paren=0;
  var re=/"(?:[^"\\]|\\.)*"|\.\.\.|@[A-Za-z_]\w*|\$[A-Za-z_]\w*|[A-Za-z_]\w*|\S/g, m, toks=[];
  while((m=re.exec(s))!==null) toks.push(m[0]);
  for(var i=0;i<toks.length;i++){
    var t=toks[i];
    if(t==='('){ paren++; continue; }
    if(t===')'){ if(paren>0) paren--; continue; }
    if(paren>0) continue;
    if(t==='{'){ depth++; if(depth>maxDepth) maxDepth=depth; continue; }
    if(t==='}'){ if(depth>0) depth--; continue; }
    if(t==='...'){ i++; continue; }
    if(t.charAt(0)==='@' || t.charAt(0)==='$' || t.charAt(0)==='"') continue;
    if(!/^[A-Za-z_]\w*$/.test(t)) continue;
    if(GQ_KEYWORDS.indexOf(t)>=0) continue;
    var alias=null, name=t;
    if(toks[i+1]===':' && /^[A-Za-z_]\w*$/.test(toks[i+2]||'')){ alias=t; name=toks[i+2]; i+=2; }
    out.push({ name:name, alias:alias, depth:depth });
  }
  return { fields:out, maxDepth:maxDepth };
}
function gqLint(p){
  if(!p || p.error) return [];
  var out=[];
  for(var i=0;i<p.vars.length;i++)
    if(!p.used[p.vars[i].name]) out.push('变量 $'+p.vars[i].name+' 声明后未被使用');
  var declared={};
  for(var j=0;j<p.vars.length;j++) declared[p.vars[j].name]=1;
  for(var k in p.used)
    if(!declared[k]) out.push('变量 $'+k+' 在查询体中使用但未声明');
  var fnames={};
  for(var f=0;f<p.frags.length;f++) fnames[p.frags[f].name]=1;
  for(var s=0;s<p.spreads.length;s++)
    if(!fnames[p.spreads[s]]) out.push('展开了未定义的片段 ...'+p.spreads[s]);
  for(var g=0;g<p.frags.length;g++)
    if(p.spreads.indexOf(p.frags[g].name)<0) out.push('片段 '+p.frags[g].name+' 定义后未被使用');
  if(!p.name && p.op!=='query') out.push('建议为 '+p.op+' 操作命名，便于服务端日志与缓存定位');
  return out;
}
function gqVarStub(p){
  if(!p || p.error) return '{}';
  var o={};
  for(var i=0;i<p.vars.length;i++){
    var v=p.vars[i], t=v.type.replace(/[!\[\]]/g,''), arr=/\[/.test(v.type);
    var sample = t==='Int' ? 0 : t==='Float' ? 0.0 : t==='Boolean' ? false : t==='ID' ? '1' : 'TODO_'+t;
    if(v.def!==null){
      try { sample = JSON.parse(v.def); } catch(e){ sample = v.def.replace(/^"|"$/g,''); }
    }
    o[v.name] = arr ? [sample] : sample;
  }
  return JSON.stringify(o, null, 2);
}
function gqCost(p){
  if(!p || p.error) return { fields:0, depth:0, score:0, level:'-' };
  var f=gqFields(p.body);
  var score = f.fields.length * 1 + f.maxDepth * f.maxDepth * 3;
  var level = score<20 ? '低' : score<60 ? '中' : score<120 ? '高' : '很高';
  return { fields:f.fields.length, depth:f.maxDepth, score:score, level:level };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { gqStrip:gqStrip, gqTokens:gqTokens, gqBalance:gqBalance, gqParse:gqParse,
    gqFields:gqFields, gqLint:gqLint, gqVarStub:gqVarStub, gqCost:gqCost };
}
if (typeof window !== 'undefined') {
  window.GraphqlForgePure = { gqStrip:gqStrip, gqTokens:gqTokens, gqBalance:gqBalance, gqParse:gqParse,
    gqFields:gqFields, gqLint:gqLint, gqVarStub:gqVarStub, gqCost:gqCost };
}
